```swift
import FirebaseFirestore

struct Order: Codable {
    @DocumentID var id: String?
    var name: String
    var quantity: Int
    var price: Double
}

struct Day: Codable {
    @DocumentID var id: String   // "1", "2" ... "31"
    var orders: [Order]
}

struct Month: Codable {
    @DocumentID var id: String   // "1" ... "12"
    var days: [Day]
}
```

