```cpp
#include <iostream>
#include <limits>
#include <cmath>

double getNumber(const std::string& prompt) {
    double x;
    while (true) {
        std::cout << prompt;
        if (std::cin >> x) break;
        std::cout << "Please enter a number.\n";
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    }
    return x;
}

int main() {
    double a = getNumber("Enter first number: ");
    double b = getNumber("Enter second number: ");

    while (true) {
        std::cout << "\nChoose operation: + - * / ^ q (quit)\n> ";
        char op;
        if (!(std::cin >> op)) break;

        switch (op) {
            case '+':
                std::cout << a << " + " << b << " = " << (a + b) << '\n';
                break;
            case '-':
                std::cout << a << " - " << b << " = " << (a - b) << '\n';
                break;
            case '*':
                std::cout << a << " * " << b << " = " << (a * b) << '\n';
                break;
            case '/':
                if (b == 0) {
                    std::cout << "Error: division by zero.\n";
                } else {
                    std::cout << a << " / " << b << " = " << (a / b) << '\n';
                }
                break;
            case '^':
                std::cout << a << " ^ " << b << " = " << std::pow(a, b) << '\n';
                break;
            case 'q':
                std::cout << "Goodbye.\n";
                return 0;
            default:
                std::cout << "Unknown operation. Try +, -, *, /, ^ or q.\n";
        }

        if (op != 'q') {
            std::cout << "Enter a new second number: ";
            b = getNumber("");
        }
    }

    return 0;
}
```

How it works:

- `getNumber` reads a number and repeats the prompt if the input isn't a number. It also clears the error state of `std::cin`, so bad input doesn't loop forever.
- The program reads two numbers first, then loops over operations.
- Division by zero is caught and reported.
- `^` uses `std::pow`, so it works with fractional exponents too.
- After each calculation, the program asks for a new second number, so you can chain calculations. Type `q` at any time to quit.

