            std::cout << "Input ended. Goodbye.\n";
            break;
        }
        if (cmd == "quit" || cmd == "exit") {
            std::cout << "Goodbye.\n";
            break;
        }

        // Put the first number back and read the rest as "a op b"
        std::cin.putback(cmd[0]);
        if (!(std::cin >> a >> op >> b)) {
