I'll write this as a MonoBehaviour that you attach to an empty GameObject in your scene. It needs the Enemy prefab assigned, and it creates a pool of four positions to spawn from. Each time the timer fires, it picks the next position in order and instantiates the prefab there.

```csharp
using System.Collections;
using UnityEngine;

public class EnemySpawner : MonoBehaviour
{
    [Header("Settings")]
    public GameObject enemyPrefab;
    public float spawnInterval = 10f;

    [Header("Spawn positions (World Space)")]
    public Vector3[] spawnPositions = {
        new Vector3(-5.5f, 3.5f, 0f),
        new Vector3(-5.5f, -3.5f, 0f),
        new Vector3(5.5f, 3.5f, 0f),
        new Vector3(5.5f, -3.5f, 0f),
    };

    private int nextPositionIndex;

    private void Start()
    {
        if (enemyPrefab == null)
        {
            Debug.LogError("EnemySpawner: No prefab assigned.");
            return;
        }

        if (spawnPositions.Length == 0)
        {
            Debug.LogError("EnemySpawner: No spawn positions defined.");
            return;
        }

        StartCoroutine(SpawnLoop());
    }

    private IEnumerator SpawnLoop()
    {
        while (true)
        {
            yield return new WaitForSeconds(spawnInterval);

            Vector3 position = spawnPositions[nextPositionIndex];
            Instantiate(enemyPrefab, position, Quaternion.identity);

            nextPositionIndex = (nextPositionIndex + 1) % spawnPositions.Length;
        }
    }
}
```

A few notes:

- The z-coordinate is set to 0 in each position. If your game uses a different plane, change that value, or remove it so the positions keep whatever z they already have.
- Each enemy is rotated with Quaternion.identity. If your prefab has a default rotation you want to keep, pass that instead.
- The positions are used in order, then repeated. If you want them chosen at random each time, replace the index logic with `spawnPositions[Random.Range(0, spawnPositions.Length)]`.
- If you want the enemies destroyed after a while, add a timeout to each instance, or destroy the spawner itself in one of the enemy prefabs.

