Here's a Unity C# script that spawns the Enemy prefab at those four positions every 10 seconds. Each enemy is placed with its own local rotation, so they face the same way regardless of where they appear. Adjust the rotation if you need them to face a different direction.

```csharp
using UnityEngine;

[RequireComponent(typeof(SpawnTimer))]
public class EnemySpawner : MonoBehaviour
{
    [Header("Prefab")]
    public GameObject enemyPrefab;

    [Header("Positions")]
    // Order matters: we rotate this array, so the enemies appear in this sequence.
    public Vector3[] positions = new Vector3[4]
    {
        new Vector3(-5.5f, 3.5f, 0f),
        new Vector3(-5.5f, -3.5f, 0f),
        new Vector3(5.5f, 3.5f, 0f),
        new Vector3(5.5f, -3.5f, 0f),
    };

    [Header("Settings")]
    public float spawnInterval = 10f;
    public Transform parent; // Optional: parent object for all spawned enemies

    private int nextIndex;
    private float nextSpawnTime;

    private void Start()
    {
        nextSpawnTime = Time.time + spawnInterval;
    }

    private void Update()
    {
        if (Time.time >= nextSpawnTime)
        {
            nextSpawnTime += spawnInterval;
            Spawn();
        }
    }

    private void Spawn()
    {
        if (enemyPrefab == null)
        {
            Debug.LogWarning($"{nameof(EnemySpawner)}: no prefab assigned.", this);
            return;
        }

        Vector3 pos = positions[nextIndex];
        pos.y += transform.position.y; // place relative to this object's Y

        GameObject enemy = Instantiate(enemyPrefab, pos, Quaternion.identity, parent);

        // Optional: give it a name so you can find it in the hierarchy.
        enemy.name = $"Enemy_{nextIndex}";

        nextIndex = (nextIndex + 1) % positions.Length;
    }
}
```

How it works:

- Positions are stored in an array, and the script walks through them in order, wrapping back to the start after the fourth. This keeps each spawn at a fixed spot and makes the order easy to change.
- Y is adjusted by the parent's Y, so if you move the spawner up, all four positions move with it. If you don't need that, leave `y` as `pos.y`.
- `Instantiate` creates the enemy at the position with no rotation. If your prefab has a Rigidbody, this spawns it with zero velocity. Add `rigidbody.velocity = Vector3.zero;` if you want to be sure.
- The parent is optional. Leave it null and the enemies sit at world coordinates. Assign a Transform in the inspector and they become children of that object.
- Timing uses `Time.time`, so it's unaffected by pauses. If you want the count to keep running when the game pauses, use `Time.unscaledTime` instead.

