The loop you sketched runs on the React thread, and while it runs nothing else does. The browser can't paint the next frame, the sound can't play, and the game feels laggy from the first step. It also never ends, because `gameOver` never changes inside the loop, so it runs forever and the page freezes.

Use `requestAnimationFrame` instead. That tells the browser to run your game logic once per displayed frame, between paints, which is what a game loop needs.

```jsx
import React, { useRef, useEffect } from "react";

function GameMain() {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    canvas.width = 800;
    canvas.height = 600;

    const player = { x: 400, y: 300, w: 40, h: 40, vx: 0, vy: 0 };
    const keys = {};

    const gravity = 0.5;
    const jump = -12;
    const groundY = 500;

    function update() {
      // Horizontal input
      if (keys["ArrowLeft"]) player.vx -= 0.8;
      if (keys["ArrowRight"]) player.vx += 0.8;

      // Friction
      player.vx *= 0.85;

      // Jump
      if (keys["ArrowUp"] && player.y >= groundY - player.h) {
        player.vy = jump;
      }

      // Gravity
      player.vy += gravity;

      // Apply velocity
      player.x += player.vx;
      player.y += player.vy;

      // Floor
      if (player.y > groundY - player.h) {
        player.y = groundY - player.h;
        player.vy = 0;
      }

      // Walls
      if (player.x < 0) player.x = 0;
      if (player.x > canvas.width - player.w) player.x = canvas.width - player.w;
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Floor
      ctx.fillStyle = "#333";
      ctx.fillRect(0, groundY, canvas.width, canvas.height - groundY);

      // Player
      ctx.fillStyle = "#4af";
      ctx.fillRect(player.x, player.y, player.w, player.h);
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    function handleKey(e) {
      keys[e.key] = e.type === "keydown";
    }

    window.addEventListener("keydown", handleKey);
    window.addEventListener("keyup", handleKey);
    loop();

    return () => {
      window.removeEventListener("keydown", handleKey);
      window.removeEventListener("keyup", handleKey);
    };
  }, []);

  return <canvas ref={canvasRef} />;
}

export default GameMain;
```

